export function findings(s){const f=[];for(const r of s.rpms){if(!r.req)f.push({id:'req:'+r.id,type:'requirement',target:r.id,title:'Missing Requirement',detail:r.title});if(!r.initiative)f.push({id:'init:'+r.id,type:'initiative',target:r.id,title:'Missing Initiative',detail:r.title});}for(const e of s.epics)if(!s.rpms.some(r=>r.initiative&&r.initiative===e.initiative))f.push({id:'epic:'+e.id,type:'epic',target:e.id,title:'Unmapped Epic',detail:e.title});for(const x of s.systems)if(!x.diagram||x.diagram.commit!==x.commit)f.push({id:'diagram:'+x.id,type:'diagram',target:x.id,title:x.diagram?'Stale architecture':'Missing architecture',detail:x.name});return f;}
export function generate(s,id){const x=s.systems.find(x=>x.id===id);if(!x)throw Error('Unknown system');const q=t=>t.replace(/["\n\r]/g,' ');x.diagram={commit:x.commit,created:new Date().toISOString(),source:'flowchart LR\n'+x.components.map((c,i)=>`  c${i}["${q(c)}"]`).join('\n')+'\n'+x.edges.map(([a,b])=>`  c${a} --> c${b}`).join('\n')};return x.diagram;}
export function apply(s,id,initiative){const f=findings(s).find(f=>f.id===id);if(!f)return false;const r=s.rpms.find(r=>r.id===f.target);const unique=prefix=>{const used=new Set(s.rpms.flatMap(r=>[r.req,r.initiative]));let n=1000;while(used.has(prefix+n))n++;return prefix+n;};if(f.type==='requirement')r.req=unique('REQ-');if(f.type==='initiative'){if(!r.req)throw Error('Create the Requirement first.');r.initiative=unique('INIT-');}if(f.type==='epic'){if(!initiative||!s.rpms.some(r=>r.initiative===initiative))throw Error('Select a valid Initiative.');s.epics.find(e=>e.id===f.target).initiative=initiative;}if(f.type==='diagram')generate(s,f.target);s.history.unshift({at:new Date().toISOString(),text:`${f.title} resolved: ${f.target} (local prototype)`});return true;}
export function importRpm(s,input){const r=Object.fromEntries(['id','title','text','source','revision'].map(k=>[k,String(input[k]||'').trim()]));if(Object.values(r).some(v=>!v))throw Error('Complete every field.');if(r.id.length>80||r.title.length>200||r.text.length>10000)throw Error('RPM exceeds supported field lengths.');if(s.rpms.some(x=>x.id===r.id))throw Error('This RPM identifier already exists. No duplicate was imported.');s.rpms.push({...r,req:null,initiative:null,system:null});s.history.unshift({at:new Date().toISOString(),text:`Imported ${r.id} from ${r.source}`});return r;}
